import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "@shared/schema";

if (!process.env.SUPABASE_URL || !process.env.SUPABASE_DB_PASSWORD) {
  throw new Error("SUPABASE_URL and SUPABASE_DB_PASSWORD environment variables are required");
}

// Extract project reference from Supabase URL
const supabaseUrl = new URL(process.env.SUPABASE_URL);
const projectRef = supabaseUrl.hostname.split('.')[0];

// Build Session Pooler connection string from actual Supabase connection info
// Format: postgresql://postgres.[PROJECT_REF]:[PASSWORD]@aws-1-us-east-2.pooler.supabase.com:5432/postgres
const connectionString = `postgresql://postgres.${projectRef}:${process.env.SUPABASE_DB_PASSWORD}@aws-1-us-east-2.pooler.supabase.com:5432/postgres`;

const client = postgres(connectionString, {
  max: 10,
});

export const db = drizzle(client, { schema });

