import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const BASE_URL = 'https://ms-pro-ecosystems.replit.app';

function generateSitemap() {
  console.log('🗺️  Генерируем sitemap.xml...\n');

  const contentDir = path.join(__dirname, '../content');
  const files = fs.readdirSync(contentDir)
    .filter(file => file.startsWith('seo_core') && file.endsWith('.json'))
    .sort();

  console.log(`Найдено ${files.length} SEO файлов:\n`);
  files.forEach(file => console.log(`  - ${file}`));

  const allUrls = new Set();

  // Статические страницы
  const staticPages = [
    '',
    'about',
    'calculator',
    'contacts',
    'mspro-quad'
  ];

  staticPages.forEach(page => {
    allUrls.add(`${BASE_URL}/${page}`);
  });

  // Загружаем все SEO записи
  files.forEach(file => {
    const filepath = path.join(contentDir, file);
    const data = JSON.parse(fs.readFileSync(filepath, 'utf8'));

    data.forEach(entry => {
      allUrls.add(`${BASE_URL}/${entry.slug}`);
    });

    console.log(`\n✅ ${file}: ${data.length} записей`);
  });

  console.log(`\n📊 Всего уникальных URL: ${allUrls.size}\n`);

  // Генерируем XML
  const urlsArray = Array.from(allUrls).sort();

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urlsArray.map(url => `  <url>
    <loc>${url}</loc>
    <lastmod>${new Date().toISOString().split('T')[0]}</lastmod>
    <changefreq>weekly</changefreq>
    <priority>${url.endsWith(BASE_URL + '/') ? '1.0' : '0.8'}</priority>
  </url>`).join('\n')}
</urlset>`;

  const sitemapPath = path.join(__dirname, '../public/sitemap.xml');
  fs.writeFileSync(sitemapPath, xml);

  console.log(`✨ Sitemap сохранён: public/sitemap.xml`);
  console.log(`📍 Содержит ${allUrls.size} URL\n`);
}

generateSitemap();

scripts/sync-to-github.ts.content:
import { Octokit } from '@octokit/rest';
import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';

const GITHUB_TOKEN = process.env.GITHUB_TOKEN || process.env.GITHUB_PERSONAL_ACCESS_TOKEN;
const REPO_OWNER = 'vladimirspecalp-hub';
const REPO_NAME = 'MSPro_eco_systems';

if (!GITHUB_TOKEN) {
  console.error('GITHUB_TOKEN environment variable is required');
  process.exit(1);
}

const octokit = new Octokit({ auth: GITHUB_TOKEN });

const filesToSync = [
  'client/src/components/layouts/MainLayout.tsx',
  'client/src/components/layouts/PageLayout.tsx',
  'client/src/components/widgets/CTABlock.tsx',
  'client/src/components/widgets/ReviewCard.tsx',
  'client/src/pages/services/ServicePage.tsx',
  'client/src/modules/geo/index.ts',
  'client/src/modules/seo/index.ts',
  'client/src/modules/crm/index.ts',
  'client/src/lib/telegramApi.ts',
  'client/src/lib/seo.ts',
  'server/crm-handler.ts',
  'server/telegram-handler.ts',
  'server/storage.ts',
  'shared/types.ts',
  'shared/schema.ts',
  'brand/BrandBook.md',
  'brand/BrandTokens.json',
  'brand/CreatedByLogaster/README.md',
];

async function syncFiles() {
  try {
    console.log('Starting GitHub sync...');

    const { data: ref } = await octokit.git.getRef({
      owner: REPO_OWNER,
      repo: REPO_NAME,
      ref: 'heads/main',
    });

    const commitSha = ref.object.sha;
    console.log('Current commit SHA:', commitSha);

    const { data: commit } = await octokit.git.getCommit({
      owner: REPO_OWNER,
      repo: REPO_NAME,
      commit_sha: commitSha,
    });

    const baseTreeSha = commit.tree.sha;

    const tree = await Promise.all(
      filesToSync.map(async (filePath) => {
        try {
          const content = readFileSync(filePath, 'utf8');
          const blob = await octokit.git.createBlob({
            owner: REPO_OWNER,
            repo: REPO_NAME,
            content: Buffer.from(content).toString('base64'),
            encoding: 'base64',
          });

          return {
            path: filePath,
            mode: '100644' as const,
            type: 'blob' as const,
            sha: blob.data.sha,
          };
        } catch (error) {
          console.error(`Error processing ${filePath}:`, error);
          return null;
        }
      })
    );

    const validTree = tree.filter(Boolean);

    const { data: newTree } = await octokit.git.createTree({
      owner: REPO_OWNER,
      repo: REPO_NAME,
      base_tree: baseTreeSha,
      tree: validTree as any,
    });

    const { data: newCommit } = await octokit.git.createCommit({
      owner: REPO_OWNER,
      repo: REPO_NAME,
      message: 'feat: Add core architecture files - layouts, widgets, modules, handlers',
      tree: newTree.sha,
      parents: [commitSha],
    });

    await octokit.git.updateRef({
      owner: REPO_OWNER,
      repo: REPO_NAME,
      ref: 'heads/main',
      sha: newCommit.sha,
    });

    console.log('✅ Successfully synced to GitHub');
    console.log('Commit URL:', `https://github.com/${REPO_OWNER}/${REPO_NAME}/commit/${newCommit.sha}`);
  } catch (error) {
    console.error('❌ GitHub sync failed:', error);
    throw error;
  }
}

syncFiles();

scripts/validate-seo.js.content:
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const seoFiles = [
  'seo_core.json',
  'seo_core_part2.json',
  'seo_core_part3.json',
  'seo_core_part4.json',
  'seo_core_part5.json'
];

const requiredFields = ['slug', 'title', 'description', 'keywords', 'h1', 'region'];

console.log('🔍 Валидация всех SEO файлов...\n');

let totalRecords = 0;
let totalValid = 0;
let totalErrors = 0;

seoFiles.forEach(fileName => {
  const filePath = path.resolve(__dirname, '../content', fileName);

  if (!fs.existsSync(filePath)) {
    console.log(`⚠️ Файл ${fileName} не найден, пропускаем...\n`);
    return;
  }

  const seoData = JSON.parse(fs.readFileSync(filePath, 'utf-8'));

  console.log(`📄 ${fileName}: ${seoData.length} записей`);

  let fileValid = 0;
  let fileErrors = 0;

  seoData.forEach((entry, index) => {
    const missing = [];

    requiredFields.forEach(field => {
      if (!entry[field] || (Array.isArray(entry[field]) && entry[field].length === 0)) {
        missing.push(field);
      }
    });

    if (missing.length > 0) {
      fileErrors++;
      console.log(`   ⚠️ Запись #${index + 1} (slug: "${entry.slug || 'отсутствует'}"):`);
      console.log(`      Отсутствуют: ${missing.join(', ')}`);
    } else {
      fileValid++;
    }
  });

  totalRecords += seoData.length;
  totalValid += fileValid;
  totalErrors += fileErrors;

  console.log(`   ✅ Валидных: ${fileValid}`);
  if (fileErrors > 0) {
    console.log(`   ⚠️ С ошибками: ${fileErrors}`);
  }
  console.log('');
});

console.log(`\n═══════════════════════════════════════════════════`);
console.log(`📊 ОБЩИЕ РЕЗУЛЬТАТЫ:`);
console.log(`   📝 Всего записей: ${totalRecords}`);
console.log(`   ✅ Валидных: ${totalValid}`);
console.log(`   ⚠️ С ошибками: ${totalErrors}`);
console.log(`═══════════════════════════════════════════════════`);

if (totalErrors === 0) {
  console.log(`\n✅ УСПЕШНО! Все ${totalRecords} записей содержат обязательные поля.`);
  process.exit(0);
} else {
  console.log(`\n⚠️ ВНИМАНИЕ! Обнаружено ${totalErrors} записей с отсутствующими полями.`);
  process.exit(1);
}

